--
-- Levels users have reached. These are history, not a derived view: the rows
-- say a level was reached once, and nothing recalculates them when a balance
-- moves.
--
-- lchen is the row that makes that concrete. The 60-point carryover in
-- 09_UserPoints.sql expired in 2025, taking the balance from 160 back to 100 --
-- so the Gold row below is a level lchen reached and no longer clears. It is
-- meant to stay. A reader that rebuilds levels from the current tally would
-- drop it, which is the difference this table exists to hold.
--

ON CONFLICT ON CONSTRAINT "UserPointLevels_UUIDs_UniqueKey" DO UPDATE SET
    "ReachedAt" = EXCLUDED."ReachedAt",
    "UpdatedBy" = 'seed';
